-- The aLogs Beta Menu's first shared test list (0.1.28-RC43), from scripts/beta-seed-0.1.28-RC43.json. INSERT OR
-- IGNORE: tests the owner already added or reworded through the API keep their own text.
-- created_at/updated_at 1793318400 = 2026-10-29 00:00 UTC.
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('under-attack-hp-number', '0.1.28-RC43', '"You''re being attacked" only on real hits', 'Tab out at full HP in the open world for 10 minutes: no alert. Get hit while tabbed out: the alert shows.', '["aLogs now reads the HP number on your bar instead of the bar''s length, so the bar flickering at full HP can''t set it off any more.","Also try: a small hit, and a hit while you''re being healed. Both should show the alert.","If it shows with nothing attacking you, say where you were standing and what was on screen."]', 0, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('interlink-3846247', '0.1.28-RC43', 'Interlink after the Whisperwake update', 'Run Interlink: the meter''s damage and HP labels match Battle Data, BREAK numbers show for the new bosses.', '["The update raised the bosses'' HP by about 60% and added Glameep, Sugartini, Jabster, Magmarex, Turbo, Jeburst and Infergon.","Compare the meter''s total with Battle Data at the end of the run.","The run should reach the leaderboard with its screenshot."]', 1, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('alpha-56-60', '0.1.28-RC43', 'Level 56-60 Alpha totals', 'Fight a level 56-60 Alpha in the world (e.g. Sugartini, Glameep): the fight total matches the HP the game shows.', NULL, 2, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('world-boss-clock', '0.1.28-RC43', 'World boss clock and result', 'Fight a world boss: the clock starts at the first hit, ends at the kill sound, and the final numbers stay on screen.', NULL, 3, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('glyph-readers', '0.1.28-RC43', 'Screen readers after the patch', 'Check the Interlink xN counter, the short names on the game menu and Egg Heist Rank Info still read right.', NULL, 4, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('egg-heist-leaderboard', '0.1.28-RC43', 'Egg Heist to the leaderboard', 'Play an Egg Heist match: it reaches the leaderboard and the rank screen updates your season standing.', NULL, 5, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('signin-window', '0.1.28-RC43', 'Sign in inside aLogs', 'Sidebar Discord button: Discord opens in an aLogs window, approve and you''re signed in; closing it cancels.', '["Also try it from the setup guide (General Settings: turn the guide on, restart aLogs).","Closing the window should bring the Sign in button back straight away."]', 6, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('capture-button-row', '0.1.28-RC43', 'Capture button follows the game''s icons', 'It sits left of Chat at the icons'' size, and hides in menus, loading screens and the map, even when dragged.', NULL, 7, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('sanctum-3846247', '0.1.28-RC43', 'Sanctum Helper on the new layouts', 'Run Egg Heist on any layout (ideally 31, 33, 38, 61 or 62): the map shows. A run with the new boss room doesn''t break it.', NULL, 8, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('profile-link-4k', '0.1.28-RC43', 'Profile link at 4K', 'Link your character from the Profile screen at 4K: it''s accepted, and your online status shows.', NULL, 9, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('photos-auto', '0.1.28-RC43', 'New photos upload by themselves', 'With "Upload new photos automatically" on, take a photo in game: it''s on your profile within a few seconds.', NULL, 10, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('patch-notes-beta', '0.1.28-RC43', 'Patch notes on the beta', 'About, Patch notes: shows "0.1.28 beta (installed)" with its notes on top.', NULL, 11, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('controller-label-combo', '0.1.28-RC43', 'Controller label and combo', 'With a controller, the capture button shows your combo under it (also when dragged), and the combo switches capture.', NULL, 12, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('own-button-picture', '0.1.28-RC43', 'Your own button picture', 'General Settings, Screen capture: "Use your own picture…" changes the button; "Use the aLogs icon again" puts it back.', NULL, 13, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('setup-guide-restart', '0.1.28-RC43', 'Setup guide', 'Turn the guide on, restart aLogs and click through it: it turns itself off at the end.', NULL, 14, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('priority-below-normal', '0.1.28-RC43', 'Priority setting', 'Set priority to Below normal: aLogs, the meter and Sanctum Helper all run at that priority.', NULL, 15, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('save-test-pictures', '0.1.28-RC43', 'Save test pictures', 'Turn it on for a while in game, use "Open the test pictures folder", then turn it off.', NULL, 16, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('hotkey-changes', '0.1.28-RC43', 'Hotkey changes', 'Change the capture hotkey (try Ctrl, Alt and Shift combos), then "No hotkey": the label goes away.', NULL, 17, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('resolutions-windowed', '0.1.28-RC43', '1080p, 1440p and windowed', 'Play at 1080p, 1440p and in a window: the button and the meter still line up and read.', NULL, 18, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('obs-recordings', '0.1.28-RC43', 'OBS and recordings', 'With OBS running: no stutter, Game Capture is normal, and "Overlays show in recordings and screenshots" works on and off.', NULL, 19, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('readings-60-30', '0.1.28-RC43', '60 vs 30 readings a second', 'DPS Meter: switch fights between 60 and 30 readings a second; both fight normally.', NULL, 20, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('profile-notes', '0.1.28-RC43', 'Profile notes', 'Open Profile in game: your collection, catches, level and EXP get noted.', NULL, 21, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('remove-photo', '0.1.28-RC43', 'Remove a photo', 'Remove a photo from your profile on the Photos page: it''s gone from the profile.', NULL, 22, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('update-next-open', '0.1.28-RC43', 'Update on next open', 'When an update is offered, choose "Next time aLogs opens": it installs when you reopen aLogs.', NULL, 23, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('sanctum-maps-release', '0.1.28-RC43', 'Sanctum Helper lets go of its maps', 'After a Sanctum run, close the game: Sanctum Helper frees its maps about a minute later.', NULL, 24, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('windows-11-tabout', '0.1.28-RC43', 'Windows 11: tabbed-out boss bar', 'On Windows 11 only: tab out during a boss fight; say whether the boss bar keeps being read (the log notes what it sees).', NULL, 25, 1793318400, 1793318400);
